const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const state={mode:'login',user:null,profile:null,books:[],offers:[],preferences:null,dashboard:null,gamification:null,alerts:[],notifications:[],shelf:'reading',chatHistory:[],chatSessionId:null,compareIds:new Set(),lastRecommendations:[],lastDiscoveryQuery:'',catalog:{offset:0,limit:12,total:0,timer:null,coverage:null,items:[]}};
