function node(tag,text='',className=''){const element=document.createElement(tag);element.textContent=text;if(className)element.className=className;return element}
function initials(text){return text.split(/\s+/).slice(0,2).map(value=>value[0]).join('').toLocaleUpperCase('tr')}
function money(minor,currency='TRY'){return minor==null?'—':`${(minor/100).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})} ${currency}`}
async function api(path,options={}){let response;try{response=await fetch(path,{credentials:'include',headers:{'Content-Type':'application/json'},...options})}catch(cause){const aborted=cause?.name==='AbortError',error=new Error(aborted?'İstek zaman aşımına uğradı. Lütfen tekrar dene.':'API sunucusuna ulaşılamadı.');error.code=aborted?'timeout':'network';throw error}if(response.status===204)return null;let data={};try{data=await response.json()}catch{}if(!response.ok){let detail=data.detail;if(Array.isArray(detail))detail=detail.map(item=>item.msg).filter(Boolean).join(' ');else if(detail&&typeof detail==='object')detail=detail.message||detail.code;const error=new Error(detail||'İşlem tamamlanamadı.');error.status=response.status;error.requestId=response.headers.get('X-Request-ID');throw error}if(path.includes('/community')&&Array.isArray(data.comments))data.comments.forEach(comment=>{comment.author.id=comment.author_id});return data}
let toastTimer;function toast(message,error=false){const box=$('#toast');box.textContent=message;box.className=`toast show${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.className='toast',3200)}

const sidebarMedia=window.matchMedia('(max-width: 900px)');
function syncSidebarControl(){
  const mobile=sidebarMedia.matches,collapsed=!mobile&&document.body.classList.contains('sidebar-collapsed'),open=mobile&&document.body.classList.contains('sidebar-open'),expanded=mobile?open:!collapsed,toggle=$('#sidebar-toggle'),sidebar=$('#primary-sidebar');
  toggle.setAttribute('aria-expanded',String(expanded));
  toggle.setAttribute('aria-label',mobile?(open?'Menüyü kapat':'Menüyü aç'):(collapsed?'Menüyü genişlet':'Menüyü daralt'));
  toggle.querySelector('span').textContent=mobile?(open?'×':'☰'):(collapsed?'›':'☰');
  sidebar.setAttribute('aria-hidden',String(mobile&&!open));
  sidebar.inert=mobile&&!open;
}
function closeMobileSidebar(){document.body.classList.remove('sidebar-open');syncSidebarControl()}
function initSidebar(){
  if(!sidebarMedia.matches&&localStorage.getItem('mihenk-sidebar-collapsed')==='true')document.body.classList.add('sidebar-collapsed');
  $('#sidebar-toggle').onclick=()=>{
    if(sidebarMedia.matches){document.body.classList.toggle('sidebar-open')}
    else{document.body.classList.toggle('sidebar-collapsed');localStorage.setItem('mihenk-sidebar-collapsed',String(document.body.classList.contains('sidebar-collapsed')))}
    syncSidebarControl();
  };
  $('#sidebar-backdrop').onclick=closeMobileSidebar;
  sidebarMedia.addEventListener('change',()=>{document.body.classList.remove('sidebar-open');syncSidebarControl()});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('sidebar-open'))closeMobileSidebar()});
  syncSidebarControl();
}

function coverFallback(book){const fallback=node('span','',`cover-fallback cover-theme-${genreTheme(book.genre)}`),genre=node('span',(book.genre||'Edebiyat').split('/')[0].trim(),'cover-genre'),title=node('strong',book.title),author=node('small',book.author||'');fallback.append(genre,title,author);return fallback}
function genreTheme(genre=''){const value=genre.toLocaleLowerCase('tr');if(/tarih|biyografi|politika/.test(value))return'burgundy';if(/bilim|fantastik|distopya/.test(value))return'cosmic';if(/şiir|deneme|edebiyat/.test(value))return'ink';if(/çocuk|genç/.test(value))return'sun';if(/polisiye|gizem|gerilim/.test(value))return'noir';return'forest'}
function cover(book,className='cover-wrap'){const wrap=node('div','',className);if(book.cover_url){const image=new Image();image.src=book.cover_url;image.alt=`${book.title} kapağı`;image.loading='lazy';image.referrerPolicy='no-referrer';image.onerror=()=>wrap.replaceChildren(coverFallback(book));wrap.append(image)}else wrap.append(coverFallback(book));return wrap}
