function renderHomeBento(){if(!state.profile||!state.gamification)return;const reading=$('#home-reading-card'),badgeCard=$('#home-badge-card'),ai=$('#home-ai-card'),current=state.profile.reading_books[0],feature=current||state.books.find(book=>book.cover_url)||state.books[0];reading.replaceChildren();const readingCopy=node('div','', 'bento-copy');readingCopy.append(node('p',current?'ŞU ANKİ YOLCULUK':'RAFINDAN BİR BAŞLANGIÇ','eyebrow'),node('h3',current?current.title:'Yeni bir dünya seç'),node('p',current?(current.total_pages?`%${current.progress_percent} tamamlandı · ${current.current_page}/${current.total_pages} sayfa`:`${current.current_page||0} sayfa ilerledin`):'Kataloğundaki renkli kapaklar arasından ruh hâline uygun bir eser bul.','muted'));if(current){const bar=node('div','', 'progress-bar'),fill=node('i');fill.style.width=`${current.progress_percent||0}%`;bar.append(fill);readingCopy.append(bar)}readingCopy.append(bentoAction(current?'Okumaya devam et':'Kataloğu keşfet',current?'library':'catalog'));if(feature)reading.append(cover(feature,'bento-cover'));reading.append(readingCopy);
  const next=state.gamification.badges.filter(item=>!item.earned).sort((a,b)=>b.progress_percent-a.progress_percent||a.goal-b.goal)[0];badgeCard.replaceChildren();const badgeVisual=node('div','', 'bento-badge-visual');badgeVisual.append(next?badgeMedallion(next,true):node('span','🏆','bento-trophy'));const badgeCopy=node('div','', 'bento-copy');badgeCopy.append(node('p',next?'SIRADAKİ BAŞARIM':'TÜMÜ TAMAM','eyebrow'),node('h3',next?next.name:'Edebiyat ustasısın'),node('p',next?`${Math.max(0,next.goal-next.progress)} adım sonra +${next.xp_reward} XP kazanacaksın.`:'Tüm temel rozetleri kazandın.','muted'),bentoAction('Rozetlerini gör','insights'));badgeCard.append(badgeVisual,badgeCopy);
  const selected=(state.preferences?.selected_traits||[]).slice(0,3);ai.replaceChildren(node('div','✦','bento-ai-orb'));const aiCopy=node('div','', 'bento-copy');aiCopy.append(node('p','BAĞLAMI BİLEN ASİSTAN','eyebrow'),node('h3','Bu ekranı seninle okuyor'),node('p',selected.length?`${selected.join(', ')} sinyallerini ve okuma geçmişini önerilere katıyorum.`:'Kitapları, raflarını ve tercihlerini konuşmanın bağlamına katıyorum.','muted'));const ask=node('button','Asistana sor','bento-link');ask.type='button';ask.onclick=()=>$('#chat-toggle').click();aiCopy.append(ask);ai.append(aiCopy)}

const searchExamples=['Melankolik bir kış akşamı için distopik bir bilim kurgu romanı arıyorum…','Kısa, atmosferik ve şaşırtıcı sonlu bir polisiye istiyorum…','İçe dönük bir karakterin umut veren dönüşüm hikâyesini arıyorum…','Savaş temalı olmayan, kolay okunan bir tarihî roman öner…'];let searchInspirationTimer=null,searchInspirationIndex=0;
function initSearchInspiration(){const field=$('#character');clearInterval(searchInspirationTimer);if(!field.value)field.placeholder=searchExamples[searchInspirationIndex];searchInspirationTimer=setInterval(()=>{if(document.activeElement===field||field.value)return;searchInspirationIndex=(searchInspirationIndex+1)%searchExamples.length;field.classList.add('placeholder-shift');setTimeout(()=>{field.placeholder=searchExamples[searchInspirationIndex];field.classList.remove('placeholder-shift')},180)},4400);updateSearchSignalSummary()}
function updateSearchSignalSummary(){const active=$$('#traits .tag.active').map(button=>button.textContent),text=$('#character').value.trim(),box=$('#search-signal-summary');if(!box)return;const pieces=[];if(active.length)pieces.push(`${active.length} karakter sinyali`);if(text)pieces.push(`${Math.min(100,Math.max(15,text.length))}% sorgu ayrıntısı`);box.classList.toggle('active',pieces.length>0);box.querySelector('p').textContent=pieces.length?`${pieces.join(' · ')} — Gemma ve katalog sıralaması birlikte çalışacak.`:'Tür, atmosfer veya karakter seç; Mihenk sinyalleri birlikte yorumlasın.'}

