function preferencePayload(overrides={}){const current=state.preferences||{};return{personality_text:current.personality_text||'',selected_traits:current.selected_traits||[],preferred_genres:current.preferred_genres||[],disliked_genres:current.disliked_genres||[],liked_styles:current.liked_styles||[],disliked_styles:current.disliked_styles||[],pace_preference:current.pace_preference||'mixed',focus_preference:current.focus_preference||'balanced',tone_preference:current.tone_preference||'balanced',violence_sensitivity:current.violence_sensitivity||0,romance_sensitivity:current.romance_sensitivity||0,spoiler_sensitivity:current.spoiler_sensitivity??2,length_preference:current.length_preference||'any',...overrides}}
