function scoreBox(label,component){const box=node('div','', 'score-component'),header=node('header');header.append(node('span',label),node('span',`%${Math.round(component.raw_score*100)}`));const bar=node('div','', 'mini-bar'),fill=node('i');fill.style.width=`${component.raw_score*100}%`;bar.append(fill);box.append(header,bar);return box}
function matchVisual(score){const percent=Math.round(score*100),visual=node('div','', 'match-visual');visual.style.setProperty('--match',`${percent*3.6}deg`);visual.setAttribute('aria-label',`Yüzde ${percent} uyum`);visual.append(node('b',`%${percent}`),node('small','UYUM'));return visual}
function recommendationCard(item){const book=state.books.find(value=>value.title===item.book_title)||{title:item.book_title,author:item.author,genre:item.genre};const card=node('article','', 'card recommendation-card'),body=node('div'),head=node('div','', 'book-head'),titles=node('div');titles.append(node('h3',item.book_title),node('p',`${item.author} · ${item.genre}`,'book-meta'));head.append(titles,matchVisual(item.match_score));const reasonBlock=node('div','', 'why-book');reasonBlock.append(node('span','✦ NEDEN BU KİTAP?'),node('p',item.reasoning,'reason'));body.append(head,reasonBlock);const breakdown=item.score_breakdown,scores=node('div','', 'score-grid');if(Number.isFinite(breakdown.ai_score)){body.append(node('p','Nihai puan · %80 Gemma 4 + %20 katalog sinyalleri','score-method'));scores.classList.add('blended-score-grid');scores.append(scoreBox('Gemma 4 · %80',{raw_score:breakdown.ai_score}),scoreBox('Katalog · %20',{raw_score:breakdown.catalog_score}))}else{scores.append(scoreBox('Karakter',breakdown.character),scoreBox('Tema',breakdown.themes),scoreBox('Geçmiş',breakdown.reading_history))}body.append(scores);if(breakdown.matched_signals.length){const signals=node('div','', 'signal-list');breakdown.matched_signals.forEach(value=>signals.append(node('span',`✓ ${value}`)));body.append(signals)}if(book.id){body.append(actionButtons(book));const feedback=node('div','', 'feedback-actions');[['✓ Tam isabet','great_match'],['× Bana göre değil','not_for_me'],['Biliyorum','already_know'],['+ Benzerleri','more_like_this']].forEach(([label,type])=>{const button=node('button',label);button.type='button';button.onclick=()=>sendRecommendationFeedback(book,type,button);feedback.append(button)});body.append(feedback)}card.append(cover(book),body);return card}
