function currentEntry(book){return [...state.profile.read_books,...state.profile.reading_books,...state.profile.to_read_books].find(item=>item.id===book.id)}
function customPayload(book,overrides={}){return{title:book.title,author:book.author||'Bilinmeyen yazar',genre:book.genre||'Genel',cover_url:book.cover_url||null,shelf:book.shelf,is_favorite:book.is_favorite||false,current_page:book.current_page||0,total_pages:book.total_pages||null,...overrides}}
