async function renderCatalog(reset=false){if(reset)state.catalog.offset=0;const grid=$('#catalog-grid'),orbit=$('#orbit-count');grid.setAttribute('aria-busy','true');if(orbit&&!state.catalog.total)orbit.setAttribute('aria-busy','true');grid.replaceChildren(...Array.from({length:6},()=>node('div','', 'skeleton')));const params=new URLSearchParams({limit:state.catalog.limit,offset:state.catalog.offset,sort:$('#catalog-sort').value}),query=$('#catalog-search').value.trim();if(query)params.set('q',query);try{const [page,coverage]=await Promise.all([api(`/catalog/books?${params}`),state.catalog.coverage?Promise.resolve(state.catalog.coverage):api('/catalog/coverage')]);state.catalog.total=page.total;state.catalog.items=page.items;state.catalog.coverage=coverage;grid.replaceChildren(...(page.items.length?page.items.map(catalogCard):[catalogEmptyState(query)]));$('#catalog-coverage').textContent=`${page.total} kitap · ${coverage.priced_books} kitapta ${coverage.offers} doğrulanmış teklif`;if(orbit&&!query){orbit.textContent=page.total.toLocaleString('tr-TR');orbit.setAttribute('aria-busy','false')}const previous=node('button','← Önceki','ghost'),next=node('button','Sonraki →','ghost');previous.disabled=state.catalog.offset===0;next.disabled=state.catalog.offset+state.catalog.limit>=page.total;previous.onclick=()=>{state.catalog.offset=Math.max(0,state.catalog.offset-state.catalog.limit);renderCatalog()};next.onclick=()=>{state.catalog.offset+=state.catalog.limit;renderCatalog()};$('#catalog-pagination').replaceChildren(previous,node('span',`Sayfa ${Math.floor(state.catalog.offset/state.catalog.limit)+1}`,'muted'),next);updateChatContext()}finally{grid.setAttribute('aria-busy','false')}}
