$('#catalog-search').oninput=()=>{clearTimeout(state.catalog.timer);state.catalog.timer=setTimeout(()=>renderCatalog(true).catch(error=>toast(error.message,true)),250)};$('#catalog-clear').onclick=()=>{$('#catalog-search').value='';renderCatalog(true)};
