async function loadCommunity(bookId){const data=await api(`/books/${bookId}/community`),stars=$('#community-rating');stars.replaceChildren(...[1,2,3,4,5].map(value=>{const button=node('button','★',value<=data.own_rating?'active':'');button.type='button';button.title=`${value} yıldız`;button.setAttribute('aria-label',`${value} yıldız ver`);button.onclick=async()=>{await api(`/me/book-ratings/${bookId}`,{method:'PUT',body:JSON.stringify({rating:value})});await loadCommunity(bookId);await refreshGamification();await renderCatalog();toast('Puanın kaydedildi.')};return button}));const distribution=data.rating_distribution||{},summary=$('#community-rating-summary');summary.replaceChildren(node('strong',data.rating_count?`${Number(data.rating_average).toFixed(1)} / 5`:'İlk puanı sen ver'),node('span',`${data.rating_count||0} okur puanı`));const bars=node('div','', 'rating-bars'),max=Math.max(1,...Object.values(distribution));[5,4,3,2,1].forEach(value=>{const row=node('div','', 'rating-bar-row'),bar=node('i');bar.style.width=`${(distribution[value]||0)/max*100}%`;row.append(node('span',`${value} ★`),node('b',''),node('small',distribution[value]||0));row.querySelector('b').append(bar);bars.append(row)});summary.append(bars);const list=$('#community-comments');list.replaceChildren(...(data.comments.length?data.comments.map(comment=>{const item=node('article','',`community-comment${comment.contains_spoiler?' spoiler':''}${comment.parent_comment_id?' reply':''}`),head=node('header'),name=node('strong',comment.author.display_name);if(comment.author.is_verified)name.append(node('span',' ✓','verified-badge'));head.append(name,node('time',new Date(comment.created_at).toLocaleDateString('tr-TR')));const body=node('p',comment.contains_spoiler?'Spoiler — görmek için tıkla':comment.content);if(comment.contains_spoiler){body.tabIndex=0;body.onclick=()=>body.textContent=comment.content;body.onkeydown=event=>{if(event.key==='Enter')body.click()}}const actions=node('div','', 'comment-actions'),reply=node('button','Yanıtla','text-button'),helpful=node('button',`${comment.own_helpful?'✓ ':''}Faydalı · ${comment.helpful_count||0}`,'text-button');reply.onclick=()=>{$('#community-parent-id').value=comment.id;$('#community-reply-context').textContent=`${comment.author.display_name} adlı okura yanıt veriyorsun.`;$('#community-reply-context').classList.remove('hidden');$('#community-comment').focus()};helpful.onclick=async()=>{await api(`/me/comments/${comment.id}/helpful`,{method:comment.own_helpful?'DELETE':'PUT'});await loadCommunity(bookId)};actions.append(reply,helpful);if(!comment.is_mine){const follow=node('button',comment.following_author?'Takibi bırak':'Takip et','text-button'),report=node('button','Şikâyet','text-button');follow.onclick=async()=>{await api(`/me/follows/${comment.author.id}`,{method:comment.following_author?'DELETE':'PUT'});await loadCommunity(bookId)};report.onclick=()=>{$('#report-form').reset();$('#report-comment-id').value=comment.id;$('#report-dialog').showModal()};actions.append(follow,report)}else{const remove=node('button','Yorumu sil','text-button');remove.onclick=async()=>{await api(`/me/book-comments/${comment.id}`,{method:'DELETE'});await loadCommunity(bookId);await refreshGamification()};actions.append(remove)}item.append(head,body,actions);return item}):[node('p','İlk yorumu sen paylaş.','muted')]))}

async function openBookDetail(book){const dialog=$('#book-detail-dialog'),content=$('#book-detail-content');content.replaceChildren(node('div','','skeleton'),node('div','','skeleton'));dialog.showModal();try{const data=await api(`/books/${book.id}/details`),hero=node('div','', 'detail-hero'),copy=node('div');copy.append(node('p',`${data.book.genre} · ${data.book.page_count||'—'} sayfa`,'eyebrow'),node('h2',data.book.title),node('p',data.book.author,'book-meta'),node('p',data.book.description,'detail-description'));hero.append(cover(data.book,'detail-cover'),copy);const match=node('section','', 'detail-match'),score=node('strong',`%${Math.round(data.ai_match.score*100)} uyum`),reasons=node('ul');data.ai_match.reasons.forEach(reason=>{const li=node('li',reason);reasons.append(li)});match.append(score,reasons);const offers=node('section','', 'detail-section');offers.append(node('h3','Güncel fiyatlar'));offers.append(...(data.offers.length?data.offers.slice(0,8).map(item=>{const a=node('a',`${item.retailer_name} · ${money(item.price_minor,item.currency)}`,'detail-offer');a.href=item.product_url;a.target='_blank';a.rel='noopener noreferrer';return a}):[node('p','Henüz doğrulanmış mağaza fiyatı yok.','muted')]));const history=node('section','', 'detail-section'),points=data.price_history.slice().reverse().slice(-24);history.append(node('h3','Fiyat geçmişi'));if(points.length){const chart=node('div','', 'price-sparkline'),min=Math.min(...points.map(p=>p.price_minor)),max=Math.max(...points.map(p=>p.price_minor));points.forEach(point=>{const bar=node('i');bar.style.height=`${20+((max-point.price_minor)/Math.max(1,max-min))*70}%`;bar.title=`${money(point.price_minor,point.currency)} · ${new Date(point.observed_at).toLocaleDateString('tr-TR')}`;chart.append(bar)});history.append(chart)}else history.append(node('p','Fiyat geçmişi veri toplandıkça oluşacak.','muted'));content.replaceChildren(hero,match,offers,history)}catch(error){content.replaceChildren(node('p',error.message,'error-line'))}}
